def solve(data):
    roman_numerals = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    result = 0
    prev_value = 0

    for char in data['s']:
        current_value = roman_numerals[char]

        if current_value > prev_value:
            result += current_value - 2 * prev_value
        else:
            result += current_value

        prev_value = current_value

    return result

def solve(data):
    # Edge cases
    if not data['s']:
        return 0
    if len(data['s']) == 1:
        return roman_to_int(data['s'])

    # Brute force method
    def roman_to_int(s):
        val = 0
        prev_val = 0
        for c in s[::-1]:
            curr_val = roman_values[c]
            if curr_val >= prev_val:
                val += curr_val
            else:
                val -= curr_val
            prev_val = curr_val
        return val

    roman_values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    # Check brute force method against public examples
    assert roman_to_int('III') == 3
    assert roman_to_int('IV') == 4
    assert roman_to_int('MCMXCIV') == 1994
    assert roman_to_int('MMMCMXCIX') == 3999

    # Efficient solution
    def roman_to_int_efficient(s):
        val = 0
        for i in range(len(s)):
            if i > 0 and roman_values[s[i]] > roman_values[s[i - 1]]:
                val += roman_values[s[i]] - 2 * roman_values[s[i - 1]]
            else:
                val += roman_values[s[i]]
        return val

    # Check efficient solution against public examples
    assert roman_to_int_efficient('III') == 3
    assert roman_to_int_efficient('IV') == 4
    assert roman_to_int_efficient('MCMXCIV') == 1994
    assert roman_to_int_efficient('MMMCMXCIX') == 3999

    # Final solution
    return roman_to_int_efficient(data['s'])
